INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Increment hier nur eine Idee?', 2, '[{"text": "Nein", "correct": true, "because": "Funktionsfähiges Produkt"}, {"text": "Ja", "correct": false, "because": "Konkretes Ergebnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Artefakt zeigt mir die Gesamtziele?', 3, '[{"text": "Product Backlog", "correct": true, "because": "Alle Anforderungen"}, {"text": "Sprint Backlog", "correct": false, "because": "Nur Sprint-Ziele"}, {"text": "Increment", "correct": false, "because": "Ergebnis, kein Plan"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sorgen hier für Transparenz?', 5, '[{"text": "Increment", "correct": true, "because": "Sichtbares Ergebnis"}, {"text": "Product Backlog", "correct": true, "because": "Zeigt Prioritäten"}, {"text": "Geheime Pläne", "correct": false, "because": "Widerspricht Transparenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sprint Backlog ist für einen Sprint. b) Increment ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Increment essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Artefakten?', 4, '[{"text": "Product Backlog", "correct": false, "because": "Basis der Planung"}, {"text": "Increment", "correct": false, "because": "Ziel jedes Sprints"}, {"text": "Unklare Ziele", "correct": true, "because": "Transparenz zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Sprint Backlog langfristig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Nur für einen Sprint"}, {"text": "Ja", "correct": false, "because": "Kurzfristige Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Artefakt wähle ich für Sprint-Ziele?', 3, '[{"text": "Sprint Backlog", "correct": true, "because": "Sprint-spezifische Aufgaben"}, {"text": "Product Backlog", "correct": false, "because": "Gesamtziele"}, {"text": "Increment", "correct": false, "because": "Ergebnis, kein Plan"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Artefakte zeigen Fortschritt?', 5, '[{"text": "Increment", "correct": true, "because": "Funktionsfähiges Ergebnis"}, {"text": "Sprint Backlog", "correct": true, "because": "Aktuelle Aufgaben"}, {"text": "Versteckte Notizen", "correct": false, "because": "Keine Transparenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Product Backlog ist dynamisch. b) Increment ist unwichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Increment zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Product Backlog", "correct": false, "because": "Grundlage der Arbeit"}, {"text": "Increment", "correct": false, "because": "Sprint-Ergebnis"}, {"text": "Unstrukturierte Ideen", "correct": true, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Product Backlog statisch?', 2, '[{"text": "Nein", "correct": true, "because": "Wird angepasst"}, {"text": "Ja", "correct": false, "because": "Dynamisch entwickelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente unterstützen die Planung?', 4, '[{"text": "Product Backlog", "correct": true, "because": "Langfristige Ziele"}, {"text": "Sprint Backlog", "correct": true, "because": "Kurzfristige Aufgaben"}, {"text": "Zufällige Listen", "correct": false, "because": "Keine Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich ohne Increment arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Increment ist Kern"}, {"text": "Ja", "correct": false, "because": "Ergebnis nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei diesen Artefakten?', 3, '[{"text": "Increment", "correct": true, "because": "Lieferbares Ergebnis"}, {"text": "Unklare Pläne", "correct": false, "because": "Transparenz nötig"}, {"text": "Leere Listen", "correct": false, "because": "Planung essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sprint Backlog ändert sich im Sprint nicht. b) Product Backlog ist flexibel.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Sprint Backlog stabil"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile haben diese Artefakte?', 5, '[{"text": "Klarheit", "correct": true, "because": "Backlogs zeigen Ziele"}, {"text": "Lieferfähigkeit", "correct": true, "because": "Increment nutzbar"}, {"text": "Verwirrung", "correct": false, "because": "Transparenz zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Sprint Backlog", "correct": false, "because": "Sprint-Planung"}, {"text": "Increment", "correct": false, "because": "Ergebnis zentral"}, {"text": "Unstrukturierte Notizen", "correct": true, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Sprint Backlog langfristig?', 3, '[{"text": "Nein", "correct": true, "because": "Nur für einen Sprint"}, {"text": "Ja", "correct": false, "because": "Kurzfristige Ziele"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Increment nutzlos ist?', 2, '[{"text": "Nein", "correct": true, "because": "Funktionsfähiges Ergebnis"}, {"text": "Ja", "correct": false, "because": "Ziel jedes Sprints"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Artefakt wähle ich für Gesamtplanung?', 4, '[{"text": "Product Backlog", "correct": true, "because": "Alle Anforderungen"}, {"text": "Increment", "correct": false, "because": "Nur Ergebnis"}, {"text": "Keine Pläne", "correct": false, "because": "Planung nötig"}]');
